from pathlib import Path
import json
import re

root = Path('/tmp/agent-sandbox-session-transcripts')
allowed = {
    'agent-sandbox',
    'agent-sandbox-dev-password',
    'sandbox',
    'sandbox-secret',
    'replace-this-value',
}
assignment = re.compile(
    r'''(?i)(\b(?:AWS_SECRET_ACCESS_KEY|AWS_ACCESS_KEY_ID|RESTIC_PASSWORD(?:_FILE|_COMMAND)?|GITHUB_TOKEN|FORGEJO_TOKEN|PLANE_TOKEN|(?:API|ACCESS|CLIENT|AUTH|BEARER|SESSION|REFRESH)[_-]?TOKEN|(?:API|CLIENT|APP|AUTH|ENCRYPTION|SIGNING|WEBHOOK)[_-]?SECRET|(?:API|ACCESS|CLIENT)[_-]?KEY|PRIVATE[_-]?KEY|(?:PASSWORD|PASSWD|SECRET|TOKEN|PAT|CREDENTIALS?)\s*[=:]\s*)(?:"([^"]*)"|'([^']*)'|([^\s,;&)}`]+))''')
url_credentials = re.compile(r'(https?://[^\s/@:]+:)[^\s/@]+(@)')
tokens = re.compile(r'(?i)\b(?:ghp|github_pat|glpat|xox[baprs]|sk)-[A-Za-z0-9_./=-]{12,}\b')
pem = re.compile(r'-----BEGIN [A-Z0-9 ]*PRIVATE KEY-----.*?-----END [A-Z0-9 ]*PRIVATE KEY-----', re.S)

def redact_string(value: str) -> str:
    def assignment_replacement(match: re.Match[str]) -> str:
        prefix, double, single, bare = match.groups()
        candidate = double if double is not None else single if single is not None else bare
        if candidate in allowed or candidate.startswith('$') or candidate.startswith('${'):
            return match.group(0)
        if double is not None:
            return f'{prefix}"[REDACTED]"'
        if single is not None:
            return f"{prefix}'[REDACTED]'"
        return f'{prefix}[REDACTED]'

    value = assignment.sub(assignment_replacement, value)
    value = url_credentials.sub(r'\1[REDACTED]\2', value)
    value = tokens.sub('[REDACTED TOKEN]', value)
    return pem.sub('[REDACTED PRIVATE KEY]', value)

def redact(value):
    if isinstance(value, str):
        return redact_string(value)
    if isinstance(value, list):
        return [redact(item) for item in value]
    if isinstance(value, dict):
        return {key: redact(item) for key, item in value.items()}
    return value

changed = 0
for path in sorted(root.rglob('*.jsonl')):
    output = []
    file_changed = False
    for line in path.read_text(errors='surrogateescape').splitlines():
        record = json.loads(line)
        redacted = redact(record)
        if redacted != record:
            file_changed = True
        output.append(json.dumps(redacted, ensure_ascii=False, separators=(',', ':')))
    text = '\n'.join(output) + '\n'
    if text != path.read_text(errors='surrogateescape'):
        path.write_text(text, encoding='utf-8')
        changed += 1
print(f'changed files: {changed}')

